        def sk4__varint(n):
            b = b''
            while True:
                x = n & 0x7f
                n >>= 7
                if n:
                    b += bytes([x | 0x80])
                else:
                    return b + bytes([x])


        def sk4__f(num, wire, payload):
            t = sk4__varint((num << 3) | wire)
