            """四源4K 线路的实测 (宽, 高)；None = 没实测过（非本源线路，别乱认）。"""
            nm = str(name or '')
            if '四源4K' in nm:
                body = nm.split('四源4K', 1)[1].lstrip('·')
            elif nm.startswith(('天堂·', '布布·', '华谊·', '苹果·')):
                body = nm
            else:
                return None
            for p in ('天堂·', '布布·', '华谊·', '苹果·'):
                if body.startswith(p):
                    body = body[len(p):]
            low = body.lower()
            for k, wh in sk4_MEASURED:
                if k in low:
                    return wh
            return None


