        def _split_episode_token(token: str) -> tuple[str, str]:
            """把 'hg-episode-v1:<q>:<vid>' 解析为 (清晰度, vid)；兼容旧格式 'hg-episode-v1:<vid>'。"""
            body = str(token or "")
            if body.startswith(EPISODE_PREFIX):
                body = body[len(EPISODE_PREFIX):]
            if ":" in body:
                head, tail = body.split(":", 1)
                if head.isdigit():
                    return head, tail
            return "1080", body

