# ======================================================================
#  第 3 段：合并门面
# ======================================================================
class Spider(_HOST_SPIDER):
    """红果 + 4K 九源 + 免扫云盘（深度分类）。"""

    NAME = '红果+4K+网盘+星光+搜剧'
    PN_TAG = '网盘'

    # 网盘详细分类：key → (标准分类 id, 名称, 额外固定参数)
    PN2_TABS = [
        ('home', '推荐', {}),
        ('1', '电影', {}),
        ('2', '剧集', {}),
        ('26', '短剧', {}),
        ('4', '动漫', {}),
        ('3', '综艺', {}),
        ('5', '纪录片', {}),
        ('1|score', '电影·高分', {'by': 'score'}),
        ('2|score', '剧集·高分', {'by': 'score'}),
        ('2|cn', '国产剧', {'area': '大陆'}),
        ('2|us', '美剧', {'area': '美国'}),
        ('2|jp', '日剧', {'area': '日本'}),
        ('2|kr', '韩剧', {'area': '韩国'}),
    ]
    COMBO = {'score': {'by': 'score'},
             'cn': {'area': '大陆'},
             'us': {'area': '美国'},
             'jp': {'area': '日本'},
             'kr': {'area': '韩国'}}

    # 标准分类 id → 该分类的中文关键词（用来核对站点返回的页面标题，防串类）
    PN_TYPE_WORDS = {
        '1': ('电影', '影片', '大片'),
        '2': ('剧集', '电视剧', '连续剧'),
        '3': ('综艺', '娱乐'),
        '4': ('动漫', '动画', '卡通'),
        '5': ('纪录',),
        '26': ('短剧', '微短剧'),
    }
    PN_WOGG_SLUG = {'1': 'dianying', '2': 'juji', '3': 'zongyi',
                    '4': 'dongman', '5': 'jilupian', '26': 'duanjv'}
    # 真正能按类型取页的站：苹果CMS 模板（webshare）+ 玩偶（wogg）
    PN_TYPED_TYPES = ('webshare', 'wogg')
    # 分类名被混淆、按名字探测不出含义的站：直接按实测内容写死映射
    # （虎斑/快映同模板：站内 1=纪录 2=剧集 3=综艺 4=动漫/综艺混合 5=音乐资源；
    #  4 混着综艺，为了保证「动漫」纯净，动漫不收这两站）
    PN_CAT_OVERRIDE = {
        '虎斑': {'5': '1', '2': '2', '3': '3'},
        '快映': {'5': '1', '2': '2', '3': '3'},
    }
    PN_MAX_PAGES = 300       # 单类最多翻到第几页（实际以站点自己的总页数为准，翻到底自然停）

    # 星光影库分类
    XZ_TABS = [('movie', 'movie', '电影'), ('tv', 'tv', '剧集'), ('anime', 'anime', '动漫'),
               ('show', 'show', '综艺'), ('doc', 'doc', '纪录片')]
    XZ_TAG = '星光'
    # 片库：截图那套「电影/电视剧/综艺/动画/纪录片 + 类型/地区/年代/排序」的浏览页
    LIB_TABS = [('movie', '电影'), ('tv', '电视剧'), ('anime', '动画'),
                ('show', '综艺'), ('doc', '纪录片')]
    LIB_SORT = [('综合', ''), ('热度', 'hot'), ('首映', 'year'), ('高分', 'score')]
    # 星光/片库：综合=默认(可播优先) 热度=评分优先 首映=按年份 高分=按评分
    XZ_SORT = [('综合', ''), ('热度', 'hot'), ('首映', 'year'), ('高分', 'score')]
    # 星光各类 → 网盘同类 tid：薄分类用来补量，厚分类用来无限续页
    LIB_PN = {'movie': '1', 'tv': '2', 'anime': '4', 'show': '3', 'doc': '5'}
    # 网盘：站点只认真实英文键，综合(默认) / 热度命中 hits / 高分 score；
    # “首映(time)”和默认同序，不单列，免得出现两个一样结果
    PN_SORT = [('综合', ''), ('热度', 'hits'), ('高分', 'score')]
    # 影探：站点的 CMS 排序参数实测无效（by=time/hits/score 返回完全一样），
    # 所以改成在拿到这一页 20 条后本地重排；热度没有字段支撑，不列
    YT_SORT = [('综合', ''), ('首映', 'new'), ('高分', 'score')]
    # 星光站自己库里动漫/综艺/纪录片很少（45/25/1 部，能播的 26/16/0），
    # 这三个 tab 直接和网盘同类的合并显示，别让页面只剩几条
    XZ_HYBRID = {'anime': '4', 'show': '3', 'doc': '5'}
    # 星光站整个打不开时的兜底：电影/剧集退到网盘同类，至少不是空页
    XZ_FALLBACK = {'movie': '1', 'tv': '2', 'anime': '4', 'show': '3', 'doc': '5'}

    # 搜剧AI：站点只有 6 个 kind 分类（feed 区要抓首页，太慢，不放进首页）
    SJ_TABS = [('kind:movie', '电影'), ('kind:series', '电视剧'), ('kind:anime', '动漫'),
               ('kind:variety', '综艺'), ('kind:documentary', '纪录片'),
               ('kind:short_drama', '短剧')]
    SJ_TAG = '搜剧'
    SJ_SEARCH_BUDGET = 3.0

    PN_FETCH_BUDGET = 4.0    # 各站并发取候选的总预算（慢站直接放弃，不拖整页）
    PN_VERIFY_BUDGET = 3.0   # 验播时限（只留 UC/夸克 真能播的）
    PN_PREFETCH_DEPTH = 3    # 第一页回来后，后台先取好后面几页
    PN_VERIFY_LIST = False   # 列表页不做逐条验播（验播放到点播时）
    PN_TTL = 900             # 分类页缓存（秒）
    PN_SEARCH_BUDGET = 5.0   # 网盘参与搜索的时限
    PN_DETAIL_BUDGET = 2.5
    PN_CACHE_TTL = 1800

    def __init__(self):
        self._base = None
        self._pn = None        # 聚合模式（17 站逐站 + 全站搜索）
        self._pn2 = None       # 免登专站模式（详细分类）
        self._star = None      # 星光影库
        self._sj = None        # 搜剧AI（souju13）
        self._grp = {}         # 同片多源折叠：代表 id -> [其余源 id]
        self._line_map = {}    # 详情 id -> [(线路名, 带前缀的集数 token)]
        self._dcache = {}      # 详情缓存（同片二次打开秒出）
        self._spd = {}         # 地址 -> (时间, 兆/秒)
        self._best = {}        # 片 -> (时间, 最优线路结果)
        self._dead = {}        # 片 -> 实测没速度的线路名集合
        self._measuring = {}   # 片 -> 是否正在后台测速
        if self._star is not None:
            try:
                self._star.init(ext_json)
            except Exception:
                pass
        if self._sj is not None:
            try:
                self._sj.init('{}')
            except Exception:
                pass
        self._cache = {}
        self._pn_cache = {}
        self._seen = {}       # 分类 key -> 已出过的片名（翻页不重复）
        self._libseen = {}    # 星光分类跨页去重（页1重置）
        self._stream = {}     # 连续分页流：{key: {'items': [...], 'real': 已抓站点页数, 'pc': 站点总页}
        self._pcache = {}     # 分类 key -> 真实总页数
        self._pfetch = {}     # 分类 key -> 预取中的页码
        self._xz_warm = False
        self.cfg = {}
        try:
            cls = globals().get('StarSpider')
            if isinstance(cls, type):
                self._star = cls()
        except Exception:
            self._star = None
        try:
            if isinstance(globals().get('BaseSpider'), type):
                self._base = BaseSpider()
        except Exception:
            self._base = None
        try:
            cls = globals().get('SJSpider')
            if isinstance(cls, type):
                self._sj = cls()
        except Exception:
            self._sj = None
        cls = globals().get('PanSpider')
        if isinstance(cls, type):
            try:
                self._pn = cls()
            except Exception:
                self._pn = None
            try:
                self._pn2 = cls()
            except Exception:
                self._pn2 = None

    # ---------------- 生命周期 ----------------
    def getName(self):
        return self.NAME

    def version(self):
        try:
            v = self._base.version()
        except Exception:
            v = ''
        return ('%s+pan' % v) if v else 'merged+pan'

    def init(self, extend=''):
        cfg = {}
        try:
            if isinstance(extend, dict):
                cfg = dict(extend)
            elif isinstance(extend, str) and extend.strip().startswith('{'):
                cfg = json.loads(extend)
        except Exception:
            cfg = {}
        if not isinstance(cfg, dict):
            cfg = {}
        self.cfg = cfg
        if self._base is not None:
            try:
                self._base.init(json.dumps(cfg, ensure_ascii=False))
            except Exception:
                pass
        pcfg = cfg.get('pan') if isinstance(cfg.get('pan'), dict) else cfg
        if not isinstance(pcfg, dict):
            pcfg = {}
        try:
            pcfg = dict(pcfg)
            pcfg.setdefault('mode', 'pan')
            ext_json = json.dumps(pcfg, ensure_ascii=False)
        except Exception:
            ext_json = '{"mode":"pan"}'
        if self._pn is not None:
            try:
                p1 = dict(pcfg)
                p1['mode'] = ''
                self._pn.init(json.dumps(p1, ensure_ascii=False))
                self._pn.SEARCH_TIMEOUT = int(cfg.get('pan_search_timeout') or 5)
                self._pn.VERIFY_TIMEOUT = int(cfg.get('pan_verify_timeout') or 4)
            except Exception:
                pass
        if self._pn2 is not None:
            try:
                self._pn2.init(ext_json)
                self._pn2.VERIFY_TIMEOUT = int(cfg.get('pan_verify_timeout') or 4)
            except Exception:
                pass
        try:
            self.PN_FETCH_BUDGET = float(cfg.get('pan_fetch_budget') or 4.0)
            self.PN_VERIFY_BUDGET = float(cfg.get('pan_verify_budget') or 4.0)
        except Exception:
            pass
        vlist = cfg.get('pan_verify_list')
        if vlist is not None:
            self.PN_VERIFY_LIST = bool(vlist) and str(vlist).lower() not in ('0', 'false', 'no')
        if self._star is not None:
            try:
                self._star.init(ext_json)
            except Exception:
                pass
        self._cache = {}
        self._pn_cache = {}
        self._seen = {}
        self._pcache = {}
        self._pfetch = {}
        self._grp = {}
        self._line_map = {}
        self._dcache = {}
        self._spd = {}
        self._best = {}
        self._dead = {}
        self._measuring = {}
        self._dead_names = {}
        self._spd_at = 0
        self._spd_load()
        if self._sj is not None:
            try:
                self._sj.init('{}')
            except Exception:
                pass
        self._warm_done = False
        self._xz_warm = False
        return None

    SPD_FILE = 'spd_cache.json'

    def _spd_path(self):
        try:
            base = os.path.dirname(os.path.abspath(__file__))
            p = os.path.join(base, self.SPD_FILE)
            if os.access(base, os.W_OK):
                return p
        except Exception:
            pass
        return os.path.join('/tmp', self.SPD_FILE)

    def _spd_load(self):
        """测速结果落盘：壳重启后不用每部片重新踩一遍死线"""
        try:
            with open(self._spd_path(), 'r', encoding='utf-8') as f:
                data = json.load(f) or {}
        except Exception:
            return
        now = time.time()
        try:
            for k, v in (data.get('best') or {}).items():
                if isinstance(v, list) and len(v) == 2 and now - float(v[0]) < 86400:
                    self._best[k] = (float(v[0]), v[1])
            for k, v in (data.get('dead') or {}).items():
                if isinstance(v, list) and len(v) == 2 and now - float(v[0]) < 86400:
                    self._dead[k] = set(v[1])
                    for nm in (v[1] or []):
                        self._dead_names[nm] = self._dead_names.get(nm, 0) + 1
            for k, v in (data.get('spd') or {}).items():
                if isinstance(v, list) and len(v) == 2 and now - float(v[0]) < 86400:
                    self._spd[k] = (float(v[0]), v[1])
        except Exception:
            pass
        try:
            p = self._spd_path() + '.log'
            try:
                lines = open(p, 'r', encoding='utf-8').read().splitlines()[-300:]
            except Exception:
                lines = []
            for ln in lines:
                try:
                    rec = json.loads(ln)
                    t = float(rec['v'][0])
                    if time.time() - t > 86400:
                        continue
                    k = rec['key']
                    if rec.get('k') == 'best':
                        self._best[tuple(k)] = (t, rec['v'][1])
                    elif rec.get('k') == 'dead':
                        st = set(rec['v'][1])
                        if st:
                            self._dead[tuple(k)] = st
                        else:
                            self._dead.pop(tuple(k), None)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            with open(self._spd_path() + '.best', 'r', encoding='utf-8') as f:
                bd = json.load(f) or {}
            if not self._best:
                for k, v in (bd.get('best') or {}).items():
                    try:
                        if time.time() - float(v[0]) < 86400:
                            self._best[k] = (float(v[0]), v[1])
                    except Exception:
                        pass
            if not self._dead:
                for k, v in (bd.get('dead') or {}).items():
                    try:
                        if time.time() - float(v[0]) < 86400:
                            self._dead[k] = set(v[1])
                    except Exception:
                        pass
        except Exception:
            pass

    def _spd_patch(self, kind, key, val):
        """线路优劣按行追加，绝不整份覆盖。"""
        try:
            try:
                json.dumps(val, ensure_ascii=False, default=str, skipkeys=True)
            except Exception:
                res = val[1] if isinstance(val, (list, tuple)) and len(val) > 1 else {}
                val = [time.time(), {'url': str((res or {}).get('url') or '')}]
            rec = {'k': kind, 'key': list(key) if isinstance(key, (list, tuple)) else str(key),
                   'v': val}
            with open(self._spd_path() + '.log', 'a', encoding='utf-8') as f:
                f.write(json.dumps(rec, ensure_ascii=False, default=str, skipkeys=True) + '\n')
        except Exception:
            pass

    def _spd_save(self, force=False):
        try:
            if not force and time.time() - self._spd_at < 20:
                return
            self._spd_at = time.time()
            safe_best = {}
            for k, v in self._best.items():
                try:
                    json.dumps(v, ensure_ascii=False, default=str, skipkeys=True)
                    safe_best[k] = v
                except Exception:
                    # 单个结果序列化不了就只存线路名+地址，别把整份缓存拖没
                    res = v[1] if isinstance(v, (list, tuple)) and len(v) > 1 else {}
                    safe_best[k] = [v[0], {'url': str((res or {}).get('url') or '')}]
            data = {'best': safe_best, 'dead': {},
                    'spd': dict(list(self._spd.items())[-120:])}
            for k, v in self._dead.items():
                data['dead'][k] = [time.time(), sorted(v)]
            try:
                txt = json.dumps(data, ensure_ascii=False, default=str, skipkeys=True)
            except Exception:
                data = {'best': {}, 'spd': {},
                        'dead': dict((k, [time.time(), sorted(v)])
                                     for k, v in self._dead.items())}
                txt = json.dumps(data, ensure_ascii=False, default=str, skipkeys=True)
            path = self._spd_path()
            tmp = path + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                f.write(txt)
            try:
                os.replace(tmp, path)
            except Exception:
                pass
        except Exception:
            pass

    def destroy(self):
        try:
            self._spd_at = 0
            self._spd_save()
        except Exception:
            pass
        for ob in (self._base, self._pn, self._pn2, self._star, self._sj):
            if ob is None:
                continue
            try:
                ob.destroy()
            except Exception:
                pass

    def isVideoFormat(self, url):
        for ob in (self._base, self._pn, self._pn2, self._star, self._sj):
            if ob is None:
                continue
            try:
                if ob.isVideoFormat(url):
                    return True
            except Exception:
                pass
        return False

